template:
{% set data = frappe.db.sql("""
    SELECT
        name AS id,
        customer_name,
        total_sale_quantity AS quantity,
        total_amount AS total_amount,
        owner AS created_by,
        outlet,
        sale_status,
        workflow_state,
        status,
        creation AS created_date
    FROM `tabSale`
    WHERE customer = %(name)s
    ORDER BY creation DESC
    LIMIT 20
""", {"name": doc.name}, as_dict=1) %}

<div class="card shadow-sm pb-0">
  <div class="card-header d-flex justify-content-between align-items-center">
    <h5 class="mb-0">Recent Payments</h5>
      <button  class="btn btn-sm btn-primary" onclick="window.open(
    '/app/sale/view/list?route_options={{ {'customer': 'C125'} | tojson | urlencode }}',
    '_blank'
)"
 href="#" id="view-all-payments">
                View All
            </button>
  </div>
{% if data %}
<div class="table-responsive mt-0">
    <table class="table table-hover align-middle mt-0">
        <thead class="table-light">
            <tr>
                <th>Invoice No</th>
                <th>Status</th>
                <th>Customer</th>
                <th>Outlet</th>
                <th class="text-end">Qty</th>
                <th class="text-end">Total Amount</th>
                <th>Created By</th>
                <th>Date</th>
            </tr>
        </thead>
        <tbody>

        {% for row in data %}

            {# ---- workflow background (30%) ---- #}
            {% set bg = "rgba(108,117,125,0.08)" %}
            {% if row.workflow_state == "open" %}
                {% set bg = "rgba(25,135,84,0.08)" %}
            {% elif row.workflow_state == "Closed" %}
                {% set bg = "rgba(25,135,84,0.08)" %}
            {% elif row.workflow_state == "Deleted" %}
                {% set bg = "rgba(220,53,69,0.08)" %}
            {% endif %}

            {# ---- status badge color ---- #}
            {% set badge = "orange" %}
            {% if row.status == "Paid" %}
                {% set badge = "green" %}
            {% elif row.status == "Unpaid" %}
                {% set badge = "red" %}
            {% endif %}

            <tr style="cursor:pointer; background-color: {{ bg }};"
                onclick="window.open('/app/sale/{{ row.id }}', '_blank')">

                <td class="fw-semibold text-primary">
                    {{ row.id }}
                </td>

                <td>
                    <span class="indicator-pill {{ badge }} no-indicator-dot whitespace-nowrap"
                          style="border:1px solid;">
                        {{ row.status }} - {{ row.workflow_state }}
                    </span>
                </td>

                <td>
                    {{ row.customer_name or "-" }}
                </td>

                <td>
                    {{ row.outlet or "-" }}
                </td>

                <td class="text-end fw-semibold">
                    {{ row.quantity | int }}
                </td>

                <td class="text-end fw-bold text-success">
                    {{ frappe.format_value(row.total_amount, {"fieldtype":"Currency"}) }}
                </td>

                <td>
                    <i class="fa fa-user me-1"></i>{{ row.created_by }}
                </td>

                <td>
                    {{ frappe.utils.format_datetime(row.created_date) }}
                </td>

            </tr>

        {% endfor %}
        </tbody>
    </table>
</div>

{% else %}
<div class="text-center text-muted py-4">
    No Data
</div>
{% endif %}
</div>
